// src/dictionary.ts
function compileDictionary(dictionaries2) {
  const byLang = {};
  const global = {};
  for (const [lang, dict] of Object.entries(dictionaries2)) {
    const compiledLang = {};
    for (const [canonical, aliases] of Object.entries(dict)) {
      compiledLang[canonical] = canonical;
      global[canonical] = canonical;
      for (const alias of aliases) {
        const lowerAlias = alias.toLowerCase();
        compiledLang[lowerAlias] = canonical;
        global[lowerAlias] = canonical;
      }
    }
    byLang[lang] = compiledLang;
  }
  return { byLang, global };
}

// src/time.ts
var en = {
  d: ["day", "days"],
  h: ["hour", "hours"],
  m: ["min", "mins", "minute", "minutes"],
  s: ["sec", "secs", "second", "seconds"]
};
var fr = {
  d: ["j", "jour", "jours"],
  h: ["heure", "heures"],
  m: ["min", "mins", "minute", "minutes"],
  s: ["sec", "secs", "seconde", "secondes"]
};
var TIME_DICTIONARIES = { en, fr };
var { byLang: TIME_BY_LANG, global: TIME_GLOBAL } = compileDictionary(TIME_DICTIONARIES);
var TIME_TO_MINUTES = {
  d: 60 * 24,
  h: 60,
  m: 1,
  s: 1 / 60
};
var resolveTimeUnit = (unit, lang) => {
  if (!unit) return "";
  const clean = unit.trim().toLowerCase();
  if (lang && TIME_BY_LANG[lang]?.[clean]) {
    return TIME_BY_LANG[lang][clean];
  }
  return TIME_GLOBAL[clean] || clean;
};

// src/units.ts
var en2 = {
  // Volume — spoons
  tsp: ["teaspoon", "teaspoons"],
  tbsp: ["tablespoon", "tablespoons"],
  // Volume — small measures (sub-tsp)
  tad: ["tads"],
  dash: ["dashes"],
  pinch: ["pinches"],
  smidgen: ["smidgen", "smidge", "smidgens"],
  drop: ["drops"],
  // Volume — cups & imperial
  cup: ["cups"],
  pt: ["pint", "pints"],
  // "quart"/"quarts" is deliberately NOT an alias for "qt" here (audit
  // 2026-07-22, finding F-01): the French word "quart" means "a quarter"
  // (as in "un quart d'heure"), not the US liquid measure — the identical
  // spelling made it a silent false-friend when both dictionaries mapped it
  // to the same canonical. "qt" is still usable by typing it directly.
  qt: [],
  gal: ["gallon", "gallons"],
  "fl oz": ["floz", "fl. oz.", "fluid ounce", "fluid ounces"],
  // Volume — metric
  ml: ["milliliter", "milliliters"],
  cl: ["centiliter", "centiliters"],
  dl: ["deciliter", "deciliters"],
  l: ["liter", "liters"],
  // Weight — metric
  mg: ["milligram", "milligrams"],
  g: ["gram", "grams"],
  kg: ["kilo", "kilos", "kilogram", "kilograms"],
  // Weight — imperial
  oz: ["ounce", "ounces"],
  lb: ["lbs", "pound", "pounds"]
};
var fr2 = {
  // Volume — cuillères
  tsp: [
    "c\xE0c",
    "cac",
    "c.\xE0.c",
    "cuill\xE8re \xE0 caf\xE9",
    "cuill\xE8res \xE0 caf\xE9",
    "cuillere a cafe",
    "cuilleres a cafe"
  ],
  tbsp: [
    "c\xE0s",
    "cas",
    "c.\xE0.s",
    "cuill\xE8re \xE0 soupe",
    "cuill\xE8res \xE0 soupe",
    "cuillere a soupe",
    "cuilleres a soupe"
  ],
  // Volume — petites mesures (sous-càc)
  tad: ["soup\xE7on", "soupcons"],
  dash: ["trait"],
  pinch: ["pinc\xE9e", "pincee", "pinc\xE9es", "pincees"],
  smidgen: ["poussi\xE8re", "poussiere", "poussi\xE8res", "poussieres"],
  drop: ["goutte", "gouttes"],
  // Pas d'alias FR pour "quart" (cf. dict EN ci-dessus) ni pour "pinte" : la
  // pinte française historique n'a pas de valeur moderne fiable et unique
  // (elle a varié de ~0,93 L à plus de 3 L selon les régions avant la
  // métrication) — mieux vaut un avertissement « unité inconnue » qu'une
  // conversion silencieusement fausse.
  "fl oz": ["once liquide", "onces liquides"],
  // Volume — métrique
  ml: ["millilitre", "millilitres"],
  cl: ["centilitre", "centilitres"],
  dl: ["d\xE9cilitre", "d\xE9cilitres", "decilitre", "decilitres"],
  l: ["litre", "litres"],
  // Volume — tasse française (250 mL), distincte du "cup" nord-américain
  // (236,588 mL) : les fusionner sous un seul canonique produisait une
  // erreur silencieuse d'environ 6 % (audit 2026-07-22, finding F-01).
  tasse: ["tasse", "tasses"],
  // Poids — métrique
  mg: ["milligramme", "milligrammes"],
  g: ["gramme", "grammes"],
  kg: ["kilo", "kilos", "kilogramme", "kilogrammes"],
  // Poids — livre française (500 g, la "livre métrique" toujours en usage
  // courant), distincte de la livre impériale "lb" (453,592 g) — les fusionner
  // produisait ~500 g → 453 g, une erreur silencieuse d'environ 10 %.
  livre: ["livre", "livres"],
  // Poids — impérial
  oz: ["once", "onces"]
};
var UNIT_DICTIONARIES = { en: en2, fr: fr2 };
var { byLang: UNIT_BY_LANG, global: UNIT_GLOBAL } = compileDictionary(UNIT_DICTIONARIES);
var UNIT_CONVERSIONS = {
  mass: {
    base: "g",
    map: {
      mg: 1e-3,
      g: 1,
      kg: 1e3,
      oz: 28.3495,
      lb: 453.592,
      // French "livre" (métrique) — see above for why this is a distinct
      // canonical from "lb" rather than an alias of it.
      livre: 500
    }
  },
  volume: {
    base: "ml",
    map: {
      ml: 1,
      cl: 10,
      dl: 100,
      l: 1e3,
      drop: 0.078,
      smidgen: 0.156,
      pinch: 0.3125,
      dash: 0.625,
      tad: 1.25,
      tsp: 4.9289,
      tbsp: 14.7868,
      cup: 236.588,
      // French "tasse" — see above for why this is a distinct canonical
      // from "cup" rather than an alias of it.
      tasse: 250,
      pt: 473.176,
      qt: 946.353,
      gal: 3785.41,
      "fl oz": 29.5735
    }
  }
};
function normalizeUnit(rawUnit, lang) {
  if (!rawUnit) return "";
  const clean = rawUnit.toLowerCase().trim();
  if (lang && UNIT_BY_LANG[lang]?.[clean]) {
    return UNIT_BY_LANG[lang][clean];
  }
  return UNIT_GLOBAL[clean] || clean;
}
function isCoarseUnit(rawUnit) {
  const normalized = normalizeUnit(rawUnit);
  if (!normalized) return false;
  for (const category of [UNIT_CONVERSIONS.mass, UNIT_CONVERSIONS.volume]) {
    const factor = category.map[normalized];
    if (factor !== void 0) return factor >= 1;
  }
  return false;
}

